function toNumberBR(value) {
  if (value === undefined || value === null || value === '') {
    return null;
  }

  let s = String(value).trim();

  // Remove R$, espaços e caracteres que não sejam número, vírgula, ponto ou sinal negativo
  s = s.replace(/[^\d,.-]/g, '');

  // Converte 1.234,56 para 1234.56
  if (s.includes(',') && s.includes('.')) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (s.includes(',')) {
    s = s.replace(',', '.');
  }

  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function toPostgresDate(value) {
  if (value === undefined || value === null || value === '') {
    return null;
  }

  const s = String(value).trim();

  // Timestamp em milissegundos
  if (/^\d+$/.test(s)) {
    return new Date(Number(s)).toISOString();
  }

  const d = new Date(s);

  if (isNaN(d.getTime())) {
    return null;
  }

  return d.toISOString();
}

const output = [];

// Pega todos os itens que vieram do Merge
const inputItems = $input.all();

for (const item of inputItems) {
  const currentJson = item.json;

  // Compatível com retorno vindo em body ou direto no json
  const response = currentJson.body ?? currentJson;

  // Cada página do HubSpot tem seu próprio results
  const results = response.results ?? [];

  for (const contact of results) {
    const p = contact.properties ?? {};

    output.push({
      json: {
        hs_object_id: String(p.hs_object_id ?? contact.id),

        firstname: p.firstname ?? null,

        hubspot_owner_id: p.hubspot_owner_id ?? null,

        equipe: p.equipe ?? null,

        status_da_matricula: p.status_da_matricula ?? null,

        valor_da_entrada: toNumberBR(p.valor_da_entrada),

        forma_de_pagamento: p.forma_de_pagamento ?? null,

        data_da_entrada: toPostgresDate(p.data_da_entrada),

        origem: p.origem ?? null,

        tipo_de_publicacao: p.tipo_de_publicacao ?? null,

        categoria_do_produto: p.categoria_do_produto ?? null
      }
    });
  }
}

return output;

