  (() => {
    const valor = $json.data_entrada;

    if (!valor) return false;

    const dataEntrada = /^\d+$/.test(String(valor))
      ? new Date(Number(valor))
      : new Date(valor);

    if (isNaN(dataEntrada.getTime())) return false;

    const hojeBR = new Date().toLocaleDateString('en-CA', {
      timeZone: 'America/Sao_Paulo'
    });

    const entradaBR = dataEntrada.toLocaleDateString('en-CA', {
      timeZone: 'America/Sao_Paulo'
    });

    return entradaBR === hojeBR;
  })()
}}
